style.css:
@-moz-document domain("instagram.com") {
/* Target the stories container and all its inner divs */
  header div[role="presentation"] div,
  header div[role="presentation"] div div,
  header div[role="presentation"] div div div {
    background: rgba(255, 255, 255, 0.2) !important; /* frosted glass */
    backdrop-filter: blur(8px) saturate(120%) !important;
    border-radius: 12px !important;
    transition: background 0.3s ease, backdrop-filter 0.3s ease;
  }

  /* Optional hover effect for stories */
  header div[role="presentation"] div:hover,
  header div[role="presentation"] div div:hover,
  header div[role="presentation"] div div div:hover {
    background: rgba(255, 255, 255, 0.3) !important;
  }
}
